import { ArrowUpRight, Users } from "lucide-react";
import { Link } from "react-router-dom";
import type { Launch } from "../types";
const compact = new Intl.NumberFormat("en-US", { notation:"compact", maximumFractionDigits:1 });
export function TokenMark({ launch, large=false }: { launch: Launch; large?: boolean }) { const hue=[...launch.symbol].reduce((a,c)=>a+c.charCodeAt(0),0)%360; return <span className={`token-mark ${large?"large":""}`} style={{backgroundImage:launch.imageUrl?`url(${launch.imageUrl})`:`linear-gradient(145deg,hsl(${hue} 58% 38%),hsl(${(hue+42)%360} 54% 16%))`}}>{launch.imageUrl?"":launch.symbol.slice(0,2)}</span>; }
export function TokenCard({ launch }: { launch: Launch }) { return <Link className="token-card" to={`/token/${launch.id}`}><div className="token-head"><TokenMark launch={launch}/><div><div className="token-title"><b>{launch.name}</b><span>${launch.symbol}</span><ArrowUpRight size={15}/></div><div className="token-pair"><em>{launch.stockSymbol??"SOL"}</em>{launch.status==="orca"?"Orca market":`${launch.progress.toFixed(0)}% bonded`}</div></div></div><p>{launch.description}</p><div className="token-stats"><Metric label="Market cap" value={`$${compact.format(launch.marketCapUsd)}`}/><Metric label="24h volume" value={`$${compact.format(launch.volume24hUsd)}`}/><Metric label="24h" value={`${launch.change24h>=0?"+":""}${launch.change24h.toFixed(1)}%`} tone={launch.change24h>=0?"up":"down"}/></div><div className="token-foot"><span><Users size={14}/>{compact.format(launch.holderCount)}</span><span>{launch.realSolReserve.toFixed(1)} SOL</span>{launch.stockSymbol&&<strong>1% rewards</strong>}</div>{launch.status!=="orca"&&<div className="progress"><i style={{width:`${launch.progress}%`}}/></div>}</Link>; }
export function Metric({label,value,tone=""}:{label:string;value:string;tone?:string}){return <div className="metric"><small>{label}</small><b className={tone}>{value}</b></div>}
