export function quoteBuy(solIn: number, rewards: boolean, virtualSol = 30, virtualTokens = 1_000_000_000) { const platformFee = solIn * .01; const rewardFee = rewards ? solIn * .01 : 0; const netSol = solIn - platformFee - rewardFee; const tokensOut = virtualTokens - virtualSol * virtualTokens / (virtualSol + netSol); return { platformFee, rewardFee, netSol, tokensOut }; }
export function quoteSell(tokenIn: number, rewards: boolean, virtualSol = 30, virtualTokens = 1_000_000_000, realSol = 0) { const grossSol = virtualSol - virtualSol * virtualTokens / (virtualTokens + tokenIn); const platformFee = grossSol * .01; const rewardFee = rewards ? grossSol * .01 : 0; return { platformFee, rewardFee, solOut: Math.max(0, Math.min(grossSol - platformFee - rewardFee, realSol)) }; }
export function buildLaunchMessage(input: { wallet: string; requestId: string; symbol: string; stockSymbol: string | null; timestamp: number }) { return ["Equity Launch", "Action: create", `Wallet: ${input.wallet}`, `Request: ${input.requestId}`, `Token: ${input.symbol.toUpperCase()}`, `Pair: ${input.stockSymbol ?? "SOL"}`, `Timestamp: ${input.timestamp}`].join("\n"); }
