import { useEffect, useMemo, useState } from "react";
import { ArrowLeft, Copy, ExternalLink, Gift, ShieldAlert, Users } from "lucide-react";
import { Link, useParams } from "react-router-dom";
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, YAxis } from "recharts";
import { toast } from "sonner";
import { api } from "../api";
import { useRuntime, useWallet } from "../context";
import { quoteBuy, quoteSell } from "../curve";
import { DEMO } from "../fixtures";
import type { Launch, Trade } from "../types";
import { Metric, TokenMark } from "../components/TokenCard";
const compact=new Intl.NumberFormat("en",{notation:"compact",maximumFractionDigits:2});const money=new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:4});
export function Token(){const {id=""}=useParams();const wallet=useWallet();const {config}=useRuntime();const [launch,setLaunch]=useState<Launch|null>(DEMO.find(x=>x.id===id)??null);const [trades,setTrades]=useState<Trade[]>([]);const [side,setSide]=useState<"buy"|"sell">("buy");const [amount,setAmount]=useState("1");useEffect(()=>{api.launch(id).then(data=>{setLaunch(data.launch);setTrades(data.trades)}).catch(()=>undefined)},[id]);const n=Math.max(0,Number(amount)||0);const q=useMemo(()=>!launch?null:side==="buy"?quoteBuy(n,Boolean(launch.stockSymbol),launch.virtualSolReserve,launch.virtualTokenReserve):quoteSell(n,Boolean(launch.stockSymbol),launch.virtualSolReserve,launch.virtualTokenReserve,launch.realSolReserve),[launch,n,side]);const chart=useMemo(()=>!launch?[]:Array.from({length:38},(_,i)=>({i,p:Math.max(.000001,launch.priceUsd||.0001)*(.42+i/61)*(1+Math.sin(i*.67)*.05)})),[launch]);if(!launch)return <main className="page empty">Market not found.</main>;const fee=q?.platformFee??0;const reward=q?.rewardFee??0;const output=side==="buy"?(q&&"tokensOut" in q?q.tokensOut:0):(q&&"solOut" in q?q.solOut:0);function submit(){if(!wallet.address)return wallet.setModalOpen(true);if(!config.transactionsEnabled)return toast.info("Trading is locked until the Solana program ID is configured on Railway.");toast.error("Connect the deployed program IDL transaction adapter before accepting live funds.")}
return <main className="page token-page"><Link className="back" to="/"><ArrowLeft/>Markets</Link><section className="token-hero"><div className="token-identity"><TokenMark launch={launch} large/><div><div><h1>{launch.name}</h1><span>${launch.symbol}</span>{launch.status==="orca"&&<em>ORCA LIVE</em>}</div><p>{launch.description}</p><footer>{launch.xUrl&&<a href={launch.xUrl} target="_blank">X <ExternalLink/></a>}<button onClick={()=>{void navigator.clipboard.writeText(launch.mint);toast.success("Mint copied")}}><Copy/> {launch.mint.slice(0,5)}…{launch.mint.slice(-4)}</button></footer></div></div><div className="hero-metrics"><Metric label="Price" value={money.format(launch.priceUsd)}/><Metric label="Market cap" value={`$${compact.format(launch.marketCapUsd)}`}/><Metric label="24h volume" value={`$${compact.format(launch.volume24hUsd)}`}/><Metric label="24h" value={`${launch.change24h>=0?"+":""}${launch.change24h.toFixed(1)}%`} tone={launch.change24h>=0?"up":"down"}/></div></section><div className="token-layout"><section className="token-main"><div className="chart-panel"><header><div><small>${launch.symbol} PRICE</small><b>{money.format(launch.priceUsd)}</b></div><span>1D</span></header><div className="chart"><ResponsiveContainer><AreaChart data={chart}><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#00c805" stopOpacity=".25"/><stop offset="1" stopColor="#00c805" stopOpacity="0"/></linearGradient></defs><CartesianGrid vertical={false} stroke="rgba(255,255,255,.05)"/><YAxis orientation="right" axisLine={false} tickLine={false} tick={{fill:"#7f887e",fontSize:10}}/><Tooltip contentStyle={{background:"#0d110d",border:"1px solid #263026"}}/><Area type="monotone" dataKey="p" stroke="#00c805" fill="url(#fill)" strokeWidth={2}/></AreaChart></ResponsiveContainer></div></div><div className="info-grid"><div className="info-panel"><small>BONDING PROGRESS</small><h2>{launch.progress.toFixed(1)}%</h2><div className="progress big"><i style={{width:`${launch.progress}%`}}/></div><p>{launch.realSolReserve.toFixed(2)} of 85 SOL. Liquidity then migrates to Orca paired with {launch.stockSymbol??"SOL"}.</p></div><div className="info-panel reward"><Gift/><b>Holder rewards</b>{launch.stockSymbol?<><div><Metric label="Paid to holders" value={`$${compact.format(launch.rewardDistributedUsd)}`}/><Metric label="Waiting" value={`${launch.rewardVaultStock.toFixed(3)} ${launch.stockSymbol}`}/></div><p>1% of trading value funds batched {launch.stockSymbol} purchases for eligible holders.</p></>:<p>This market does not collect the extra holder reward fee.</p>}</div></div><div className="activity"><header><b>Market activity</b><span>{launch.txCount.toLocaleString()} transactions</span></header><table><thead><tr><th>Type</th><th>Wallet</th><th>SOL</th><th>Tokens</th></tr></thead><tbody>{(trades.length?trades:mock(launch)).map(t=><tr key={t.id}><td className={t.side}>{t.side.toUpperCase()}</td><td>{t.wallet}</td><td>{t.solAmount.toFixed(3)}</td><td>{compact.format(t.tokenAmount)}</td></tr>)}</tbody></table></div></section><aside className="trade-card"><div className="trade-tabs"><button className={side==="buy"?"active":""} onClick={()=>setSide("buy")}>Buy</button><button className={side==="sell"?"active":""} onClick={()=>setSide("sell")}>Sell</button></div><label>You pay</label><div className="trade-input"><input value={amount} onChange={e=>setAmount(e.target.value.replace(/[^0-9.]/g,""))}/><b>{side==="buy"?"SOL":launch.symbol}</b></div><Row l="You receive" v={`${compact.format(output)} ${side==="buy"?launch.symbol:"SOL"}`} strong/><Row l="Platform fee (1%)" v={`${fee.toFixed(4)} SOL`}/><Row l={`Holder rewards${launch.stockSymbol?" (1%)":""}`} v={launch.stockSymbol?`${reward.toFixed(4)} SOL`:"Off"} green={Boolean(launch.stockSymbol)}/><Row l="Route" v={launch.status==="orca"?`Orca / ${launch.stockSymbol??"SOL"}`:"Virtual curve"}/><button className="primary full" disabled={!n} onClick={submit}>{wallet.address?(side==="buy"?`Buy ${launch.symbol}`:`Sell ${launch.symbol}`):"Connect wallet"}</button>{!config.transactionsEnabled&&<div className="locked"><ShieldAlert/>Preview mode. Set the deployed program ID on Railway after audit to enable transactions.</div>}<div className="creator"><span>Creator</span><b>{launch.creatorWallet.slice(0,5)}…{launch.creatorWallet.slice(-4)}</b><span>Dev buy</span><b>{launch.devBuySol.toFixed(1)} SOL · {launch.devSupplyPct.toFixed(1)}%</b><span>Holders</span><b><Users/> {compact.format(launch.holderCount)}</b></div></aside></div></main>}
function Row({l,v,strong,green}:{l:string;v:string;strong?:boolean;green?:boolean}){return <div className={`trade-row ${strong?"strong":""}`}><span>{l}</span><b className={green?"green":""}>{v}</b></div>}function mock(l:Launch):Trade[]{return Array.from({length:6},(_,i)=>({id:`${l.id}-${i}`,wallet:`${["7mQx","K8p2","3Zva","P9eL","6Twu","A1cx"][i]}…${["fQ2","9Mp","k71","w30","Jq4","8xd"][i]}`,side:i===2||i===5?"sell":"buy",solAmount:.17+((i*37)%20)/10,tokenAmount:82900+i*182300,priceUsd:l.priceUsd,createdAt:Date.now()-i*90000}))}
