import { PieChart, WalletCards } from "lucide-react";
import { Link } from "react-router-dom";
import { useWallet } from "../context";
export function Portfolio(){const wallet=useWallet();return <main className="page simple-page"><span className="eyebrow">WALLET OVERVIEW</span><h1>Portfolio</h1><p>Token positions, launches, and claimable stock rewards in one place.</p>{!wallet.address?<div className="empty-card"><WalletCards/><h2>Connect your wallet</h2><p>Use Phantom or MetaMask to load your Solana positions.</p><button className="primary" onClick={()=>wallet.setModalOpen(true)}>Connect wallet</button></div>:<><div className="simple-stats"><Box l="Portfolio value" v="$0.00"/><Box l="Claimable rewards" v="$0.00"/><Box l="Launches created" v="0"/></div><div className="empty-card"><PieChart/><h2>No positions found</h2><p>Your indexed on-chain holdings will appear here.</p><Link className="primary" to="/">Explore markets</Link></div></>}</main>}function Box({l,v}:{l:string;v:string}){return <div><small>{l}</small><b>{v}</b></div>}
