import { useEffect, useMemo, useState } from "react";
import { Check, ImagePlus, Loader2, ShieldCheck, X } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { api } from "../api";
import { useRuntime, useWallet } from "../context";
import { buildLaunchMessage, quoteBuy } from "../curve";
import type { StockOption } from "../types";

type Form={name:string;symbol:string;description:string;stockSymbol:string;xUrl:string;websiteUrl:string;telegramUrl:string};
const empty:Form={name:"",symbol:"",description:"",stockSymbol:"SOL",xUrl:"",websiteUrl:"",telegramUrl:""};
const url=(value:string,prefix="https://")=>value.trim()?(/^https?:\/\//i.test(value.trim())?value.trim():`${prefix}${value.trim()}`):null;
export function Create(){
  const nav=useNavigate(); const wallet=useWallet(); const {config}=useRuntime(); const [form,setForm]=useState(empty); const [stocks,setStocks]=useState<StockOption[]>([]); const [devBuy,setDevBuy]=useState(false); const [devSol,setDevSol]=useState(1); const [ack,setAck]=useState(false); const [file,setFile]=useState<File|null>(null); const [preview,setPreview]=useState(""); const [busy,setBusy]=useState(false);
  useEffect(()=>{api.stocks().then(data=>setStocks(data.stocks)).catch((error)=>toast.error(error.message))},[]); useEffect(()=>()=>{if(preview)URL.revokeObjectURL(preview)},[preview]);
  const reward=form.stockSymbol!=="SOL"; const stock=stocks.find(item=>item.symbol===form.stockSymbol); const quote=useMemo(()=>quoteBuy(devBuy?devSol:0,reward),[devBuy,devSol,reward]); const ready=form.name.trim().length>=2&&form.symbol.length>=2&&(!reward||(Boolean(stock?.mint)&&ack));
  const set=(key:keyof Form,value:string)=>setForm(current=>({...current,[key]:value}));
  async function launch(){if(!wallet.address){wallet.setModalOpen(true);return}if(!ready)return toast.error("Complete the required launch details.");setBusy(true);try{const clientRequestId=crypto.randomUUID();const timestamp=Date.now();const message=buildLaunchMessage({wallet:wallet.address,requestId:clientRequestId,symbol:form.symbol,stockSymbol:reward?form.stockSymbol:null,timestamp});const signed=await wallet.signMessage(message);let imageId:string|null=null;if(file){const body=new FormData();body.set("file",file);body.set("creatorWallet",wallet.address);body.set("clientRequestId",clientRequestId);body.set("symbol",form.symbol);body.set("stockSymbol",reward?form.stockSymbol:"");body.set("timestamp",String(timestamp));body.set("signature",signed.signature);body.set("message",signed.message);imageId=(await api.upload(body)).imageId}const result=await api.createLaunch({creatorWallet:wallet.address,clientRequestId,name:form.name.trim(),symbol:form.symbol,description:form.description.trim(),imageId,stockSymbol:reward?stock!.symbol:null,stockName:reward?stock!.name:null,stockMint:reward?stock!.mint:null,devBuySol:devBuy?devSol:0,xUrl:url(form.xUrl),websiteUrl:url(form.websiteUrl),telegramUrl:url(form.telegramUrl,"https://t.me/"),timestamp,signature:signed.signature,message:signed.message});toast.success("Launch signed and saved");nav(`/token/${result.launch.id}`)}catch(error){toast.error(error instanceof Error?error.message:"Launch failed.")}finally{setBusy(false)}}
  return <main className="page create-page"><div className="create-heading"><span className="eyebrow">CREATE ON {config.network.toUpperCase()}</span><h1>Launch a market</h1><p>Start on a virtual curve, then graduate into Orca liquidity.</p></div><div className="create-layout"><section className="form-stack"><Panel n="01" title="Token details"><div className="token-fields"><label className="artwork">{preview?<span style={{backgroundImage:`url(${preview})`}}/>:<><ImagePlus/><small>PNG, JPG or WebP<br/>max 3 MB</small></>}<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" onChange={e=>{const next=e.target.files?.[0]??null;setFile(next);setPreview(next?URL.createObjectURL(next):"")}}/>{file&&<button onClick={(e)=>{e.preventDefault();setFile(null);setPreview("")}}><X size={14}/></button>}</label><div className="field-grid"><Field label="Name"><input value={form.name} maxLength={32} placeholder="Neural Index" onChange={e=>set("name",e.target.value)}/></Field><Field label="Ticker"><input value={form.symbol} maxLength={10} placeholder="NEUR" onChange={e=>set("symbol",e.target.value.replace(/[^a-z0-9]/gi,"").toUpperCase())}/></Field><Field label="Description" wide><textarea rows={4} maxLength={360} value={form.description} placeholder="What is this community building?" onChange={e=>set("description",e.target.value)}/></Field></div></div></Panel><Panel n="02" title="Pair and holder rewards"><div className="pair-choices"><Choice selected={!reward} title="Standard SOL" text="1% platform fee. Graduates to token/SOL." onClick={()=>set("stockSymbol","SOL")}/><Choice selected={reward} title="Stock rewards" text="1% platform + 1% stock reward reserve." onClick={()=>set("stockSymbol",stocks[0]?.symbol??"SOL")}/></div>{reward&&<><Field label="Verified xStock pair"><select value={form.stockSymbol} onChange={e=>{set("stockSymbol",e.target.value);setAck(false)}}>{stocks.map(item=><option key={item.symbol} value={item.symbol} disabled={item.halted}>{item.symbol} · {item.name}{item.halted?" — halted":""}</option>)}</select></Field><label className="legal-check"><input type="checkbox" checked={ack} onChange={e=>setAck(e.target.checked)}/><span>I understand tokenized stocks are regulated products, can be halted, and may be restricted in my jurisdiction.</span></label></>}</Panel><Panel n="03" title="Socials" optional><div className="field-grid"><Field label="X account or post"><input value={form.xUrl} placeholder="x.com/account or /status/…" onChange={e=>set("xUrl",e.target.value)}/></Field><Field label="Website"><input value={form.websiteUrl} placeholder="yourproject.xyz" onChange={e=>set("websiteUrl",e.target.value)}/></Field><Field label="Telegram" wide><input value={form.telegramUrl} placeholder="t.me/yourcommunity" onChange={e=>set("telegramUrl",e.target.value)}/></Field></div></Panel><Panel n="04" title="Initial developer buy" optional><div className="switch-row"><div><b>Buy in the launch transaction</b><small>Optional. Maximum 10 SOL.</small></div><button className={`switch ${devBuy?"on":""}`} onClick={()=>setDevBuy(!devBuy)}><i/></button></div>{devBuy&&<><div className="dev-amount"><span>Developer buy</span><b>{devSol.toFixed(1)} SOL</b></div><input type="range" min="0.1" max="10" step="0.1" value={devSol} onChange={e=>setDevSol(Number(e.target.value))}/></>}</Panel></section><aside className="launch-summary"><h2>Launch summary</h2><div className="summary-token"><span>{form.symbol.slice(0,2)||"EL"}</span><div><b>{form.name||"Your token"}</b><small>${form.symbol||"TICKER"} / {form.stockSymbol}</small></div></div><Row label="Curve" value="Virtual SOL"/><Row label="Graduation" value="85 SOL"/><Row label="Platform fee" value="1.00%"/><Row label="Holder rewards" value={reward?"1.00%":"Off"} accent={reward}/><Row label="Total fee" value={reward?"2.00%":"1.00%"} strong/>{devBuy&&<><Row label="Net to curve" value={`${quote.netSol.toFixed(3)} SOL`}/><Row label="Estimated tokens" value={quote.tokensOut.toLocaleString("en",{notation:"compact"})}/></>}<div className="custody-note"><ShieldCheck/>Your wallet signs every launch and transaction.</div><button className="primary full" disabled={!ready||busy} onClick={()=>void launch()}>{busy?<><Loader2 className="spin"/>Waiting for wallet</>:wallet.address?"Review and sign launch":"Connect wallet"}</button>{!config.transactionsEnabled&&<p className="preview-warning">Preview mode. Deploy the audited program and set its ID on Railway to enable on-chain submission.</p>}</aside></div></main>;
}
function Panel({n,title,optional,children}:{n:string;title:string;optional?:boolean;children:React.ReactNode}){return <div className="form-panel"><header><span>{n}</span><h2>{title}</h2>{optional&&<small>OPTIONAL</small>}</header>{children}</div>}; function Field({label,wide,children}:{label:string;wide?:boolean;children:React.ReactNode}){return <label className={wide?"field wide":"field"}><span>{label}</span>{children}</label>}; function Choice({selected,title,text,onClick}:{selected:boolean;title:string;text:string;onClick:()=>void}){return <button className={`pair-choice ${selected?"selected":""}`} onClick={onClick}><b>{title}</b>{selected&&<Check/>}<small>{text}</small></button>}; function Row({label,value,accent,strong}:{label:string;value:string;accent?:boolean;strong?:boolean}){return <div className={`summary-row ${strong?"strong":""}`}><span>{label}</span><b className={accent?"green":""}>{value}</b></div>}
